function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) {
  useEffect(() => { const close = (e: KeyboardEvent) => e.key === 'Escape' && onClose(); window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, [onClose]);
  return <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="fixed inset-0 z-50 grid place-items-center bg-[#03050c]/80 p-5 backdrop-blur-sm" onMouseDown={onClose}>
    <motion.div initial={{ opacity: 0, y: 12, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} role="dialog" aria-modal="true" aria-labelledby="modal-title" onMouseDown={e => e.stopPropagation()} className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl border border-white/[.1] bg-[#0B1020] p-6 shadow-2xl">
      <div className="mb-6 flex items-center justify-between"><h2 id="modal-title" className="font-['Space_Grotesk'] text-xl font-semibold">{title}</h2><button type="button" aria-label="Close modal" onClick={onClose} className="grid size-9 place-items-center rounded-lg text-[#8D96AD] hover:bg-white/[.06] hover:text-white"><X size={18} /></button></div>{children}
    </motion.div>
  </motion.div>;
}
function Intro({ onEnter }: { onEnter: () => void }) {
  const [stage, setStage] = useState(0); const reduce = useReducedMotion();
  useEffect(() => { const a = window.setTimeout(() => setStage(1), 850); const b = window.setTimeout(() => setStage(2), 1700); const c = window.setTimeout(onEnter, 2850); return () => { window.clearTimeout(a); window.clearTimeout(b); window.clearTimeout(c); }; }, [onEnter]);
  return <motion.main initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="nexus-noise nexus-grid relative flex min-h-[100dvh] items-center justify-center overflow-hidden bg-[#060914] px-6 py-12">
    <div className="absolute left-1/2 top-1/2 size-[480px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-[#6C63FF]/[.09] blur-[110px]" />
    <div className="relative z-10 w-full max-w-5xl">
      <div className="mb-20 flex items-center justify-between"><Logo /><span className="font-mono text-[10px] tracking-[.16em] text-[#8D96AD]">SYSTEM 01 / 03</span></div>
      <div className="grid items-end gap-12 md:grid-cols-[1.2fr_.8fr]"><div>
        <motion.div animate={reduce ? {} : { rotate: [0, 4, -4, 0] }} transition={{ duration: 2.8, repeat: Infinity }} className="mb-7 grid size-20 place-items-center rounded-3xl border border-[#00D9FF]/30 bg-[#6C63FF]/15 shadow-[0_0_50px_#6C63FF33]"><Logo compact /></motion.div>
        <p className="mb-5 font-mono text-xs uppercase tracking-[.24em] text-[#00D9FF]">{stage === 0 ? 'CONNECTING TO NEXUS...' : stage === 1 ? 'NEXUS ONLINE' : 'YOUR STUDENT JOURNEY, INTELLIGENTLY CONNECTED.'}</p>
        <motion.h1 initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="max-w-2xl font-['Space_Grotesk'] text-6xl font-bold leading-[.93] tracking-[-.08em] text-[#F5F7FF] sm:text-8xl">Learn.<br /><span className="text-[#6C63FF]">Discover.</span><br />Build. <span className="text-[#27E6A7]">Become.</span></motion.h1>
      </div><motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: .45 }} className="border-l border-[#6C63FF]/30 pl-6"><p className="max-w-xs text-sm leading-7 text-[#8D96AD]">Your scattered ambitions, connected. One intelligent place for the work that matters next.</p><button type="button" onClick={onEnter} className="mt-8 inline-flex items-center gap-3 rounded-xl bg-[#F5F7FF] px-5 py-3 text-sm font-bold text-[#060914] transition hover:bg-[#00D9FF]">Enter NEXUS <ArrowRight size={16} /></button><button type="button" onClick={onEnter} className="mt-4 block font-mono text-[10px] uppercase tracking-[.16em] text-[#8D96AD] hover:text-white">Skip intro</button><p className="mt-3 font-mono text-[10px] uppercase tracking-[.16em] text-[#8D96AD]">DEMO MODE · LOCAL INTELLIGENCE</p></motion.div></div>
      <div className="mt-24 grid grid-cols-3 border-t border-white/[.08] pt-5 text-[10px] uppercase tracking-[.16em] text-[#8D96AD]"><span>01 / orient</span><span>02 / connect</span><span className="text-right">03 / become</span></div>
    </div>
  </motion.main>;
}
