function MorePage() { return <div className="nexus-in"><PageHeader eyebrow="Everything connected" title="MORE" description="Keep exploring the parts of NEXUS that make the system yours." /><div className="grid gap-3 sm:grid-cols-2">{navItems.slice(4).concat([{ href: '/profile', label: 'Profile', icon: UserRound }, { href: '/settings', label: 'Settings', icon: Settings }]).map(item => { const I = item.icon; return <Link key={item.href} href={item.href} className="flex items-center gap-4 rounded-2xl border border-white/[.07] bg-[#0B1020] p-5 transition hover:-translate-y-0.5 hover:border-[#6C63FF]/50"><div className="grid size-11 place-items-center rounded-xl bg-[#6C63FF]/10 text-[#6C63FF]"><I size={20} /></div><span className="flex-1 font-semibold">{item.label}</span><ArrowRight size={16} className="text-[#566079]" /></Link>; })}</div></div>; }
function AppShell() {
  const [location, setLocation] = useLocation(); const [tasks, setTasks] = useStoredState<Task[]>('nexus-tasks', initialTasks); const [theme, setTheme] = useStoredState('nexus-theme', 'dark'); const [reduced, setReduced] = useStoredState('nexus-reduced-motion', false); const [introSeen, setIntroSeen] = useStoredState('nexus-intro-seen', false); const [xp, setXp] = useStoredState('nexus-xp', 2480); const [roadmapDone, setRoadmapDone] = useStoredState<number[]>('nexus-roadmap', []); const [plannerTasks, setPlannerTasks] = useStoredState<string[]>('nexus-planner', []); const [search, setSearch] = useState(false); const [notifications, setNotifications] = useState(false);
  useEffect(() => { document.documentElement.classList.toggle('light', theme === 'light'); document.documentElement.classList.toggle('dark', theme !== 'light'); document.documentElement.classList.toggle('reduced-motion', reduced); }, [theme, reduced]);
  const toggleTask = (id: number) => setTasks(tasks.map(t => t.id === id ? { ...t, done: !t.done } : t));
  if (!introSeen) return <Intro onEnter={() => setIntroSeen(true)} />;
  const page = location === '/' ? <Dashboard tasks={tasks} toggleTask={toggleTask} setTasks={setTasks} onOpenAI={() => setLocation('/ai')} xp={xp} setXp={setXp} /> : location === '/ai' ? <AIPage /> : location === '/scholarships' ? <ScholarshipsPage /> : location === '/opportunities' ? <OpportunitiesPage /> : location === '/skills' ? <SkillsPage roadmapDone={roadmapDone} setRoadmapDone={setRoadmapDone} setXp={setXp} /> : location === '/planner' ? <PlannerPage plannerTasks={plannerTasks} setPlannerTasks={setPlannerTasks} /> : location === '/campus' ? <CampusPage /> : location === '/progress' ? <ProgressPage tasks={tasks} /> : location === '/gamification' ? <GamificationPage xp={xp} setXp={setXp} tasks={tasks} /> : location === '/profile' ? <ProfilePage /> : location === '/settings' ? <SettingsPage theme={theme} setTheme={setTheme} reduced={reduced} setReduced={setReduced} /> : location === '/more' ? <MorePage /> : <Dashboard tasks={tasks} toggleTask={toggleTask} setTasks={setTasks} onOpenAI={() => setLocation('/ai')} xp={xp} setXp={setXp} />;
  return <div className="nexus-noise min-h-[100dvh] bg-[#060914] text-[#F5F7FF]"><Sidebar location={location} onSearch={() => setSearch(true)} /><div className="lg:pl-[248px]"><Topbar onSearch={() => setSearch(true)} onNotify={() => setNotifications(true)} /><main className="mx-auto max-w-[1440px] px-5 pb-28 pt-8 md:px-8 lg:pb-10">{page}</main></div><MobileNav location={location} />{search && <SearchOverlay onClose={() => setSearch(false)} />}{notifications && <Notifications onClose={() => setNotifications(false)} />}</div>;
}
export default AppShell;